@section('content')<div class="code-shell"><div class="code-card"><h1>Join a Group</h1><p>Enter the unique 6-character code shared by the photographer or group organiser.</p>@if($errors->any())<div class="alert alert-error">{{ $errors->first() }}</div>@endif<form method="POST" action="{{ route('groups.join-by-code') }}" id="join-form">@csrf<input type="hidden" name="event_code" id="code"><div class="code-boxes">@for($i=0;$i<6;$i++)<input inputmode="text" autocapitalize="characters" maxlength="1" aria-label="Code character {{ $i+1 }}">@endfor</div><button class="btn btn-primary btn-lg full" id="join" disabled>Continue</button><a class="back" href="{{ route('welcome.start') }}">Back</a></form></div></div>@endsection
@push('styles')<style>.code-shell{min-height:calc(100vh - 60px);display:grid;place-items:center;padding:24px}.code-card{width:min(100%,480px);text-align:center;background:#fff;padding:32px;border-radius:20px;box-shadow:var(--shadow-lg)}.code-card>p{color:var(--muted);margin:6px 0 22px}.code-boxes{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin-bottom:20px}.code-boxes input{aspect-ratio:1;padding:0;text-align:center;font-size:24px;font-weight:700}.full{width:100%;justify-content:center}.back{display:block;margin-top:16px;color:var(--muted)}</style>@endpush
@push('scripts')<script>const ds=[...document.querySelectorAll('.code-boxes input')],h=document.getElementById('code'),j=document.getElementById('join'),form=document.getElementById('join-form');function clean(v){return v.toUpperCase().replace(/[^A-HJ-NP-Z2-9]/g,'')}function s(){h.value=ds.map(x=>x.value).join('');j.disabled=h.value.length<6}ds.forEach((b,i)=>{b.oninput=()=>{b.value=clean(b.value).slice(-1);if(b.value&&ds[i+1])ds[i+1].focus();s()};b.onkeydown=e=>{if(e.key==='Backspace'&&!b.value&&ds[i-1])ds[i-1].focus()};b.onpaste=e=>{e.preventDefault();[...clean(e.clipboardData.getData('text')).slice(0,6)].forEach((v,k)=>ds[k].value=v);s()}});form.onsubmit=()=>{j.disabled=true;j.textContent='Checking…'}</script>@endpush
